"""Factorial of a Number — linear recursion.

Time: O(n)   Space: O(n) call stack (an iterative loop would be O(1))
"""


class Solution:
    def factorial(self, n: int) -> int:
        if n <= 1:
            return 1
        return n * self.factorial(n - 1)
